import{_ as i,C as o,c as e,o as t,j as a,G as l,a0 as r,b as n,a as s,w as c,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Definizione degli obiettivi per i giocatori di bocce","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/goals/index.md","filePath":"it/education/goals/index.md"}');const p=i({name:"it/education/goals/index.md"},[["render",function(i,u,p,g,b,m){const h=o("AdBanner"),v=o("Mermaid"),q=o("AdInArticle");return t(),e("div",null,[u[1]||(u[1]=a("h1",{id:"definizione-degli-obiettivi-per-i-giocatori-di-bocce",tabindex:"-1"},[s("Definizione degli obiettivi per i giocatori di bocce "),a("a",{class:"header-anchor",href:"#definizione-degli-obiettivi-per-i-giocatori-di-bocce","aria-label":'Permalink to "Definizione degli obiettivi per i giocatori di bocce"'},"​")],-1)),l(h),u[2]||(u[2]=r('<p>Gli obiettivi chiari sono la tua bussola. Ti danno una direzione per il tuo allenamento, ti motivano quando le cose si fanno difficili e ti permettono di misurare i progressi. Senza obiettivi, stai solo lanciando bocce. Con obiettivi, stai costruendo qualcosa.</p><div class="tip custom-block"><p class="custom-block-title">Il principio fondamentale</p><p><strong>Un obiettivo senza un piano è solo un desiderio.</strong> Stabilisci obiettivi chiari, suddividili, concentrati su ciò che puoi controllare e monitora i tuoi progressi.</p></div><h2 id="perche-gli-obiettivi-sono-importanti" tabindex="-1">Perché gli obiettivi sono importanti <a class="header-anchor" href="#perche-gli-obiettivi-sono-importanti" aria-label="Permalink to &quot;Perché gli obiettivi sono importanti&quot;">​</a></h2><p>Gli obiettivi hanno molteplici scopi:</p><ul><li><strong>Indicazione:</strong> Sapere su cosa lavorare</li><li><strong>Motivazione:</strong> Avere qualcosa per cui impegnarsi</li><li><strong>Misurazione:</strong> Tieni traccia dei tuoi progressi</li><li><strong>Focus:</strong> Dai priorità al tuo tempo limitato</li></ul><p>Per il giocatore autonomo, gli obiettivi sono particolarmente importanti. Senza un allenatore che ti spinge, sono i tuoi obiettivi a diventare la tua guida.</p><h2 id="i-tre-tipi-di-obiettivi" tabindex="-1">I tre tipi di obiettivi <a class="header-anchor" href="#i-tre-tipi-di-obiettivi" aria-label="Permalink to &quot;I tre tipi di obiettivi&quot;">​</a></h2><p>Non tutti gli obiettivi sono uguali. Comprendere le diverse tipologie ti aiuta a stabilire obiettivi migliori.</p><h3 id="_1-obiettivi-di-risultato" tabindex="-1">1. Obiettivi di risultato <a class="header-anchor" href="#_1-obiettivi-di-risultato" aria-label="Permalink to &quot;1. Obiettivi di risultato&quot;">​</a></h3><p><strong>Cosa:</strong> Il risultato finale che desideri <strong>Esempio:</strong> &quot;Vinci il campionato regionale&quot; <strong>Livello di controllo:</strong> Basso - dipende dagli avversari, dalle condizioni, dalla fortuna</p><h3 id="_2-obiettivi-di-prestazione" tabindex="-1">2. Obiettivi di prestazione <a class="header-anchor" href="#_2-obiettivi-di-prestazione" aria-label="Permalink to &quot;2. Obiettivi di prestazione&quot;">​</a></h3><p><strong>Cosa:</strong> Standard di prestazione specifici <strong>Esempio:</strong> &quot;Raggiungi l&#39;80% di precisione negli esercizi di tiro&quot; <strong>Livello di controllo:</strong> Medio - dipende principalmente da te</p><h3 id="_3-obiettivi-del-processo" tabindex="-1">3. Obiettivi del processo <a class="header-anchor" href="#_3-obiettivi-del-processo" aria-label="Permalink to &quot;3. Obiettivi del processo&quot;">​</a></h3><p><strong>Cosa:</strong> Azioni e comportamenti che controlli <strong>Esempio:</strong> &quot;Completare la mia routine pre-tiro a ogni lancio&quot; <strong>Livello di controllo:</strong> Alto - dipende interamente da te</p><h3 id="la-gerarchia-degli-obiettivi" tabindex="-1">La gerarchia degli obiettivi <a class="header-anchor" href="#la-gerarchia-degli-obiettivi" aria-label="Permalink to &quot;La gerarchia degli obiettivi&quot;">​</a></h3>',15)),(t(),n(d,null,{default:c(()=>[l(v,{id:"mermaid-71",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BObiettivo%20del%20risultato%20%3Cbr%2F%3E%20Il%20sogno%5D%20--%3E%20B%5BObiettivi%20di%20prestazione%20%3Cbr%2F%3E%20Pietre%20miliari%5D%0A%20%20%20%20B%20--%3E%20C%5BObiettivi%20del%20processo%20%3Cbr%2F%3E%20Azioni%20quotidiane%5D%0A%0A%20%20%20%20A2%5B%26quot%3BVinci%20il%20campionato%20regionale%26quot%3B%5D%20--%3E%20B2%5B%26quot%3BPrecisione%20di%20tiro%20dell%26%2339%3B80%25%26quot%3B%5D%0A%20%20%20%20B2%20--%3E%20C2%5B%26quot%3BRoutine%20completa%20pre-tiro%20%3Cbr%2F%3E%20ogni%20lancio%26quot%3B%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B%20fill%3A%23fff9c4%0A%20%20%20%20style%20C%20fill%3A%23c8e6c9%0A%20%20%20%20style%20A2%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B2%20fill%3A%23fff9c4%0A%20%20%20%20style%20C2%20fill%3A%23c8e6c9%0A"})]),fallback:c(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[3]||(u[3]=r('<div class="warning custom-block"><p class="custom-block-title">Intuizione chiave</p><p><strong>Concentra la maggior parte della tua attenzione sugli obiettivi di processo.</strong> Sono ciò che controlli e ti portano ai risultati che desideri.</p><ul><li><strong>Obiettivi di risultato:</strong> Basso controllo, alta motivazione</li><li><strong>Obiettivi di prestazione:</strong> Controllo medio, progressi misurabili</li><li><strong>Obiettivi del processo:</strong> Alto controllo, attenzione quotidiana ← <strong>Concentrati qui</strong></li></ul></div><h2 id="il-quadro-smart" tabindex="-1">Il quadro SMART <a class="header-anchor" href="#il-quadro-smart" aria-label="Permalink to &quot;Il quadro SMART&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Lista di controllo degli obiettivi SMART</p><p>Ogni obiettivo dovrebbe essere:</p><ul><li>✅ <strong>S</strong>pecifico - Chiaro e ben definito</li><li>✅ <strong>Misurabile</strong> - Puoi monitorare i progressi</li><li>✅ <strong>Raggiungibile</strong> - Sfidante ma possibile</li><li>✅ <strong>R</strong>levante - Allineato con il tuo quadro generale</li><li>✅ **Temporalmente vincolato - Ha una scadenza</li></ul></div>',3)),l(q),u[4]||(u[4]=r('<h3 id="s-specific" tabindex="-1">S - Specific <a class="header-anchor" href="#s-specific" aria-label="Permalink to &quot;S - Specific&quot;">​</a></h3><p>❌ &quot;Migliora il tiro&quot; ✅ &quot;Migliora la precisione del mio tiro diretto da 8 metri&quot;</p><h3 id="m-misurabile" tabindex="-1">M - Misurabile <a class="header-anchor" href="#m-misurabile" aria-label="Permalink to &quot;M - Misurabile&quot;">​</a></h3><p>❌ &quot;Spara con maggiore precisione&quot; ✅ &quot;Segna almeno 24/30 nell&#39;esercizio di tiro a segno&quot;</p><h3 id="a-raggiungibile" tabindex="-1">A - Raggiungibile <a class="header-anchor" href="#a-raggiungibile" aria-label="Permalink to &quot;A - Raggiungibile&quot;">​</a></h3><p>❌ &quot;Non sbagliare mai un colpo&quot; (impossibile) ✅ &quot;Migliorare la precisione del 10% in 8 settimane&quot; (impegnativo ma realistico)</p><h3 id="r-rilevante" tabindex="-1">R - Rilevante <a class="header-anchor" href="#r-rilevante" aria-label="Permalink to &quot;R - Rilevante&quot;">​</a></h3><p>❌ &quot;Correre una maratona&quot; (non direttamente correlato) ✅ &quot;Migliora l&#39;equilibrio e la stabilità per un lancio migliore&quot; (supporta il tuo gioco)</p><h3 id="t-limitato-nel-tempo" tabindex="-1">T - Limitato nel tempo <a class="header-anchor" href="#t-limitato-nel-tempo" aria-label="Permalink to &quot;T - Limitato nel tempo&quot;">​</a></h3><p>❌ &quot;Un giorno starò meglio&quot; ✅ &quot;Entro il 15 marzo, raggiungerò...&quot;</p><h2 id="esempi-di-obiettivi-per-la-boccia" tabindex="-1">Esempi di obiettivi per la boccia <a class="header-anchor" href="#esempi-di-obiettivi-per-la-boccia" aria-label="Permalink to &quot;Esempi di obiettivi per la boccia&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tipo</th><th>Obiettivo pessimo</th><th>Obiettivo SMART</th></tr></thead><tbody><tr><td>Risultato</td><td>&quot;Vinci di più&quot;</td><td>&quot;Raggiungere le semifinali del Torneo di Primavera&quot;</td></tr><tr><td>Prestazione</td><td>&quot;Punta meglio&quot;</td><td>&quot;Raggiungi il 70% dei punti entro 50 cm a 8 m di distanza&quot;</td></tr><tr><td>Processo</td><td>&quot;Esercitati di più&quot;</td><td>&quot;Completa 3 sessioni di allenamento mirate a settimana&quot;</td></tr></tbody></table><h2 id="scomporre-i-grandi-obiettivi" tabindex="-1">Scomporre i grandi obiettivi <a class="header-anchor" href="#scomporre-i-grandi-obiettivi" aria-label="Permalink to &quot;Scomporre i grandi obiettivi&quot;">​</a></h2><p>Gli obiettivi ambiziosi possono sembrare opprimenti. Suddividili in parti più piccole:</p><h3 id="esempio-quot-vinci-il-campionato-del-club-tra-12-mesi-quot" tabindex="-1">Esempio: &quot;Vinci il campionato del club (tra 12 mesi)&quot; <a class="header-anchor" href="#esempio-quot-vinci-il-campionato-del-club-tra-12-mesi-quot" aria-label="Permalink to &quot;Esempio: &amp;quot;Vinci il campionato del club (tra 12 mesi)&amp;quot;&quot;">​</a></h3><p><strong>Obiettivo annuale:</strong> Vincere il campionato di club</p><p><strong>Obiettivi trimestrali:</strong></p><ul><li>D1: Migliorare la precisione di tiro al 75%</li><li>D2: Sviluppare una routine pre-tiro coerente</li><li>D3: Gestire le situazioni di pressione</li><li>D4: Prestazioni ottimali e preparazione alla competizione</li></ul><p><strong>Obiettivi mensili (Q1):</strong></p><ul><li>Mese 1: stabilire la linea di base, identificare i punti deboli</li><li>Mese 2: Concentrati sulla tecnica di tiro</li><li>Mese 3: Aggiungi pressione alla pratica di tiro</li></ul><p><strong>Obiettivi settimanali (mese 2):</strong></p><ul><li>Settimana 1: 3 sessioni di tiro, analisi video</li><li>Settimana 2: Lavorare sul problema tecnico identificato</li><li>Settimana 3: Aumentare gradualmente la distanza</li><li>Settimana 4: verifica dei progressi, modifica del piano</li></ul><h2 id="collegare-gli-obiettivi-al-tuo-quot-perche-quot" tabindex="-1">Collegare gli obiettivi al tuo &quot;perché&quot; <a class="header-anchor" href="#collegare-gli-obiettivi-al-tuo-quot-perche-quot" aria-label="Permalink to &quot;Collegare gli obiettivi al tuo &amp;quot;perché&amp;quot;&quot;">​</a></h2><p>Gli obiettivi funzionano meglio se collegati a una motivazione più profonda.</p><p>Chiediti:</p><ul><li>Perché voglio raggiungere questo obiettivo?</li><li>Cosa significherà per me?</li><li>Come mi sentirò quando avrò successo?</li><li>Cosa mi spinge a migliorare?</li></ul><p>Scrivi le tue risposte. Riprendile quando la motivazione svanisce.</p><h2 id="in-questa-sezione" tabindex="-1">In questa sezione <a class="header-anchor" href="#in-questa-sezione" aria-label="Permalink to &quot;In questa sezione&quot;">​</a></h2><ul><li><strong><a href="/it/education/goals/smart-goals">Obiettivi SMART in dettaglio</a></strong> - Approfondimento sulla creazione di obiettivi efficaci</li><li><strong><a href="/it/educazione/obiettivi/pianificazione">Creare il tuo piano di allenamento</a></strong> - Trasforma gli obiettivi in azioni</li></ul><h2 id="riepilogo-regole-per-la-definizione-degli-obiettivi" tabindex="-1">Riepilogo: Regole per la definizione degli obiettivi <a class="header-anchor" href="#riepilogo-regole-per-la-definizione-degli-obiettivi" aria-label="Permalink to &quot;Riepilogo: Regole per la definizione degli obiettivi&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regola n. 1: la regola del controllo</p><p><strong>Concentrati sugli obiettivi di processo (ciò che controlli) piuttosto che sugli obiettivi di risultato.</strong> Gli obiettivi di processo portano agli obiettivi di prestazione, che portano agli obiettivi di risultato.</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 2: la regola SMART</p><p><strong>Gli obiettivi devono essere specifici, misurabili, raggiungibili, pertinenti e vincolati al tempo.</strong> Obiettivi vaghi producono risultati vaghi. Gli obiettivi SMART producono progresso.</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 3: la regola della ripartizione</p><p><strong>Gli obiettivi più ambiziosi necessitano di traguardi trimestrali, mensili e settimanali.</strong> Suddividi i grandi obiettivi in piccoli passi concreti che puoi completare questa settimana.</p></div><div class="tip custom-block"><p class="custom-block-title">Regola n. 4: La regola della connessione</p><p><strong>Collega gli obiettivi al tuo &quot;perché&quot; più profondo.</strong> Quando la motivazione svanisce, il tuo &quot;perché&quot; ti fa andare avanti.</p></div><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>Un obiettivo senza un piano è solo un desiderio.</p></blockquote><p>Stabilisci obiettivi chiari. Suddividili in più fasi. Concentrati su ciò che puoi controllare. Monitora i tuoi progressi.</p>',37)),l(h)])}]]);export{u as __pageData,p as default};
